  forecastHelperText: string;
  forecastActionDisabled: boolean;
  runForecast: () => void;

  baselineTargetsRef: React.RefObject<DemandForecast[] | null>;
  demandTargets: DemandForecast[];
  roster: Shift[];
  shiftTemplates: ShiftTemplate[];
  forecastError: string | null;

  onBulkSave: (targets: BulkTarget[]) => void;
};

// ---------------------------------------------------------------------------
// Inline CSV parsing helpers (pure JS, no library)
// ---------------------------------------------------------------------------

/** Very simple CSV line splitter (handles quoted fields) */
function splitCsvLine(line: string): string[] {
  const result: string[] = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      inQuotes = !inQuotes;
    } else if (ch === ',' && !inQuotes) {
      result.push(current.trim());
      current = '';
    } else {
      current += ch;
    }
  }
  result.push(current.trim());
  return result;
}

/** Strip currency symbols / commas and parse float */
function parseRevenue(raw: string): number | null {
  const cleaned = raw.replace(/[$€£,]/g, '').trim();
  if (cleaned === '') return null;
  const n = parseFloat(cleaned);
  return isFinite(n) ? n : null;
}

/** Try to detect and normalise date to YYYY-MM-DD */
function normaliseDate(raw: string): string | null {
  const s = raw.trim();
  if (!s) return null;

  // YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    const d = new Date(s + 'T00:00:00');
    return isNaN(d.getTime()) ? null : s;
  }

  // MM/DD/YYYY
  const mdy = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (mdy) {
    const [, m, d, y] = mdy;
    const iso = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
    const dt = new Date(iso + 'T00:00:00');
    return isNaN(dt.getTime()) ? null : iso;
  }

  // DD/MM/YYYY (ambiguous — treat as DD/MM when day > 12)
  const dmy = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (dmy) {
    const [, d, m, y] = dmy;
    const iso = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
    const dt = new Date(iso + 'T00:00:00');
    return isNaN(dt.getTime()) ? null : iso;
  }

  return null;
}

type PosPreviewRow = {
  date: string;
  revenue: number;
  covers: number | null;
  notes: string | null;
};

/**
 * Parse pasted CSV text into preview rows + validation error strings.
 * Expected columns (case-insensitive): date, revenue, covers (optional), notes (optional)
 */
function parsePosPreview(text: string): { rows: PosPreviewRow[]; errors: string[] } {
  const lines = text
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter((l) => l.length > 0);

  if (lines.length === 0) {
    return { rows: [], errors: ['No content found in pasted text.'] };
  }

  const headerCells = splitCsvLine(lines[0]).map((h) => h.toLowerCase().replace(/\s+/g, ''));
  const dateIdx = headerCells.findIndex((h) => h === 'date');
  const revenueIdx = headerCells.findIndex((h) => h === 'revenue' || h === 'sales');
  const coversIdx = headerCells.findIndex((h) => h === 'covers' || h === 'guests');
  const notesIdx = headerCells.findIndex((h) => h === 'notes' || h === 'note');

  const errors: string[] = [];

  if (dateIdx === -1) {
    errors.push('Missing required column: date');
  }
  if (revenueIdx === -1) {
    errors.push('Missing required column: revenue (or sales)');
  }
  if (errors.length > 0) {
    return { rows: [], errors };
  }

  const rows: PosPreviewRow[] = [];

  for (let i = 1; i < lines.length; i++) {
    const cells = splitCsvLine(lines[i]);
    const rowNum = i; // 1-based after header

    const rawDate = cells[dateIdx] ?? '';
    const rawRevenue = cells[revenueIdx] ?? '';

    const normDate = normaliseDate(rawDate);
    if (!normDate) {
      errors.push(`Row ${rowNum}: invalid or missing date "${rawDate}"`);
      continue;
    }

    const revenue = parseRevenue(rawRevenue);
    if (revenue === null) {
      errors.push(`Row ${rowNum}: invalid or missing revenue "${rawRevenue}"`);
      continue;
    }

    const rawCovers = coversIdx !== -1 ? (cells[coversIdx] ?? '') : '';
    const coversNum = rawCovers.trim() !== '' ? parseInt(rawCovers.trim(), 10) : null;
    const covers = coversNum !== null && isFinite(coversNum) ? coversNum : null;

    const notes = notesIdx !== -1 && (cells[notesIdx] ?? '').trim() !== ''
      ? cells[notesIdx].trim()
      : null;

    rows.push({ date: normDate, revenue, covers, notes });
  }

  return { rows, errors };
}

