// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export const DemandSection = ({
  fallbackMode,
  setFallbackMode,
  fallbackForm,
  updateFallbackField,
  handleFallbackSubmit,
  fallbackError,
  fallbackMessage,
  targetForm,
  updateTargetField,
  handleTargetSubmit,
  targetError,
  forecastButtonLabel,
  forecastHelperText,
  forecastActionDisabled,
  runForecast,
  baselineTargetsRef,
  demandTargets,
  roster,
  shiftTemplates,
  forecastError,
  onBulkSave,
}: Props) => {
  const { t } = useT();
  const colorScheme = useColorScheme();
  const colors = Colors[colorScheme ?? 'light'];
  const local = makeLocalStyles(colors);

  // -------------------------------------------------------------------------
  // Local POS state
  // -------------------------------------------------------------------------
  const [pasteText, setPasteText] = React.useState('');
  const [posState, setPosState] = React.useState<
    'idle' | 'preview' | 'generating' | 'done' | 'error'
  >('idle');
  const [parsedPosRows, setParsedPosRows] = React.useState<PosPreviewRow[]>([]);
  const [posErrors, setPosErrors] = React.useState<string[]>([]);
  const [posConfig, setPosConfig] = React.useState({
    revenuePerWorkerHour: '50',
    avgShiftHours: '8',
  });
  const [posErrorMessage, setPosErrorMessage] = React.useState('');

  // -------------------------------------------------------------------------
  // POS handlers
  // -------------------------------------------------------------------------
  const handlePosPreview = React.useCallback(() => {
    const { rows, errors } = parsePosPreview(pasteText);
    setParsedPosRows(rows);
    setPosErrors(errors);
    setPosState(rows.length > 0 ? 'preview' : 'idle');
  }, [pasteText]);

  const handlePosGenerate = React.useCallback(async () => {
    setPosState('generating');
    try {
      const revenuePerWorkerHour =
        parseFloat(posConfig.revenuePerWorkerHour) ||
        DEFAULT_POS_CONFIG.revenuePerWorkerHour;
      const avgShiftHours =
        parseFloat(posConfig.avgShiftHours) ||
        DEFAULT_POS_CONFIG.avgShiftHours;

      const results = await forecastDemandFromPOS(parsedPosRows, {
        ...DEFAULT_POS_CONFIG,
        revenuePerWorkerHour,
        avgShiftHours,
      });

      const targets: BulkTarget[] = results.map((r) => ({
        date: r.date,
        role: fallbackForm.role || 'worker',
        required: r.required,
        source: r.source ?? 'pos',
        notes: r.notes ?? '',
        lowerBound: r.lowerBound ?? r.required,
        upperBound: r.upperBound ?? r.required,
        confidence: r.confidence ?? 1,
      }));

      onBulkSave(targets);
      setPosState('done');
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      setPosErrorMessage(msg);
      setPosState('error');
    }
  }, [parsedPosRows, posConfig, fallbackForm.role, onBulkSave]);

  // -------------------------------------------------------------------------
  // Render
  // -------------------------------------------------------------------------
  return (
    <SectionCard
      title={t('scheduler.demand.sectionTitle')}
      subtitle={t('scheduler.demand.sectionSubtitle')}
      tooltip={t('scheduler.demand.tooltip')}
    >
      <ThemedView style={styles.fallbackCard}>
        <View style={styles.rowBetween}>
          <ThemedText type="defaultSemiBold">{t('scheduler.demand.quickSetupTab')}</ThemedText>
          {/* [2][8] Badge: theme-aware surface + AA-compliant text colour */}
          <View style={[styles.badge, local.fallbackBadge]}>
            <ThemedText style={local.badgeText}>{t('scheduler.demand.fallbackTab')}</ThemedText>
          </View>
        </View>
        <ThemedText style={styles.mutedText}>
          {t('scheduler.demand.quickSetupDesc')}
        </ThemedText>

        {/* Toggle chips row */}
        <View style={styles.inlineActions}>
          {/* [5][6] Inactive chip uses textSecondary (6.86:1); active has white on teal (6.88:1) */}
          <Pressable
            onPress={() => setFallbackMode('homogeneous')}
            accessibilityRole="radio"
            accessibilityState={{ selected: fallbackMode === 'homogeneous' }}
            style={[
              local.toggleChip,
              fallbackMode === 'homogeneous' && local.toggleChipActive,
            ]}
          >
            <ThemedText
              style={[
                local.toggleChipText,
                fallbackMode === 'homogeneous' && local.toggleChipTextActive,
              ]}
            >
              {t('scheduler.demand.homogeneous')}
            </ThemedText>
          </Pressable>
          <Pressable
            onPress={() => setFallbackMode('manual')}
            accessibilityRole="radio"
            accessibilityState={{ selected: fallbackMode === 'manual' }}
            style={[
              local.toggleChip,
              fallbackMode === 'manual' && local.toggleChipActive,
            ]}
          >
            <ThemedText
              style={[
                local.toggleChipText,
                fallbackMode === 'manual' && local.toggleChipTextActive,
              ]}
            >
              {t('scheduler.demand.manualCounts')}
            </ThemedText>
          </Pressable>
          {/* POS Import chip — added after manual chip */}
