  const { acknowledgeBreak, dismissPrompt, minutesActive, promptVisible, recordInteraction } =
    useSessionWellness();

  // ── UI state ──────────────────────────────────────────────────────────────
  const [savedOnboardingProgress, setSavedOnboardingProgress] =
