  // ── Derived: roster grouped by date ──────────────────────────────────────
  const rosterByDate = useMemo(() => {
    const map = new Map<string, typeof roster>();
    for (const shift of roster) {
      const existing = map.get(shift.date) ?? [];
      existing.push(shift);
      map.set(shift.date, existing);
    }
    return map;
  }, [roster]);

  // ── Derived: upcoming shifts (next 7 days) ────────────────────────────────
  const upcomingShifts = useMemo(() => {
    const today = new Date();
    const limit = new Date(today);
    limit.setDate(limit.getDate() + 7);
    return roster.filter((s) => {
      const d = new Date(s.date);
      return d >= today && d <= limit;
