      },
    ];
  }, [t, workers.length, shiftTemplates.length, roster]);

  // ── Derived: onboarding progress ─────────────────────────────────────────
  const onboardingProgress = useMemo(() => {
    const completed = onboardingSteps.filter((s) => s.completed).length;
    return { completed, total: onboardingSteps.length };
  }, [onboardingSteps]);

  // ── Persist onboarding progress ───────────────────────────────────────────
  useEffect(() => {
    if (!accountId) return;
    const completed = onboardingSteps.filter((s) => s.completed).map((s) => s.id);
    if (
      savedOnboardingProgress &&
      JSON.stringify(savedOnboardingProgress.completedSteps) === JSON.stringify(completed)
    )
      return;
    upsertOnboardingProgress(accountId, completed).then(setSavedOnboardingProgress);
  }, [accountId, onboardingSteps, savedOnboardingProgress]);

  // ── Forecast UI helpers ───────────────────────────────────────────────────
  const forecastButtonLabel = forecasting
    ? t('forecast.running')
    : dataStatus === 'ready'
    ? t('forecast.refresh')
    : t('forecast.run');

  const forecastHelperText = useMemo(() => {
    if (forecastError) return forecastError;
    if (dataStatus === 'ready') return t('forecast.ready');
    if (dataStatus === 'stale') return t('forecast.stale');
    return t('forecast.idle');
  }, [forecastError, dataStatus, t]);

  const forecastActionDisabled = forecastLoading || forecasting;

  // ── Action banner helper ──────────────────────────────────────────────────
